  9403  static bool
  9404  wasm_loader_push_frame_offset(WASMLoaderContext *ctx, uint8 type,
  9405                                bool disable_emit, int16 operand_offset,
  9406                                char *error_buf, uint32 error_buf_size)
  9407  {
  9408      uint32 cell_num_to_push, i;
  9409
  9410      if (type == VALUE_TYPE_VOID)
  9411          return true;
  9412
  9413      /* only check memory overflow in first traverse */
  9414      if (ctx->p_code_compiled == NULL) {
  9415          if (!check_offset_push(ctx, error_buf, error_buf_size))
  9416              return false;
  9417      }
  9418
  9419      if (disable_emit)
  9420          *(ctx->frame_offset)++ = operand_offset;
  9421      else {
  9422          emit_operand(ctx, ctx->dynamic_offset);
  9423          *(ctx->frame_offset)++ = ctx->dynamic_offset;
  9424          ctx->dynamic_offset++;
  9425          if (ctx->dynamic_offset > ctx->max_dynamic_offset) {
  9426              ctx->max_dynamic_offset = ctx->dynamic_offset;
  9427              if (ctx->max_dynamic_offset >= INT16_MAX) {
  9428                  goto fail;
  9429              }
  9430          }
  9431      }
  9432
  9433      if (is_32bit_type(type))
  9434          return true;
  9435
  9436      cell_num_to_push = wasm_value_type_cell_num(type) - 1;
  9437      for (i = 0; i < cell_num_to_push; i++) {
  9438          if (ctx->p_code_compiled == NULL) {
  9439              if (!check_offset_push(ctx, error_buf, error_buf_size))
  9440                  return false;
  9441          }
  9442
  9443          ctx->frame_offset++;
  9444          if (!disable_emit) {
  9445              ctx->dynamic_offset++;
  9446              if (ctx->dynamic_offset > ctx->max_dynamic_offset) {
  9447                  ctx->max_dynamic_offset = ctx->dynamic_offset;
  9448                  if (ctx->max_dynamic_offset >= INT16_MAX)
  9449                      goto fail;
  9450              }
  9451          }
  9452      }
  9453
  9454      return true;
  9455
  9456  fail:
  9457      set_error_buf(error_buf, error_buf_size,
  9458                    "fast interpreter offset overflow");
  9459      return false;
  9460  }
