  9462  /* This function should be in front of wasm_loader_pop_frame_ref
  9463      as they both use ctx->stack_cell_num, and ctx->stack_cell_num
  9464      will be modified by wasm_loader_pop_frame_ref */
  9465  static bool
  9466  wasm_loader_pop_frame_offset(WASMLoaderContext *ctx, uint8 type,
  9467                               char *error_buf, uint32 error_buf_size)
  9468  {
  9469      /* if ctx->frame_csp equals ctx->frame_csp_bottom,
  9470         then current block is the function block */
  9471      uint32 depth = ctx->frame_csp > ctx->frame_csp_bottom ? 1 : 0;
  9472      BranchBlock *cur_block = ctx->frame_csp - depth;
  9473      int32 available_stack_cell =
  9474          (int32)(ctx->stack_cell_num - cur_block->stack_cell_num);
  9475      uint32 cell_num_to_pop;
  9476
  9477      /* Directly return success if current block is in stack
  9478         polymorphic state while stack is empty. */
  9479      if (available_stack_cell <= 0 && cur_block->is_stack_polymorphic)
  9480          return true;
  9481
  9482      if (type == VALUE_TYPE_VOID)
  9483          return true;
  9484
  9485      /* Change type to ANY when the stack top is ANY, so as to avoid
  9486         popping unneeded offsets, e.g. if type is I64/F64, we may pop
  9487         two offsets */
  9488      if (available_stack_cell > 0 && *(ctx->frame_ref - 1) == VALUE_TYPE_ANY)
  9489          type = VALUE_TYPE_ANY;
  9490
  9491      cell_num_to_pop = wasm_value_type_cell_num(type);
  9492
  9493      /* Check the offset stack bottom to ensure the frame offset
  9494         stack will not go underflow. But we don't thrown error
  9495         and return true here, because the error msg should be
  9496         given in wasm_loader_pop_frame_ref */
  9497      if (!check_offset_pop(ctx, cell_num_to_pop))
  9498          return true;
  9499
  9500      ctx->frame_offset -= cell_num_to_pop;
  9501      if ((*(ctx->frame_offset) > ctx->start_dynamic_offset)
  9502          && (*(ctx->frame_offset) < ctx->max_dynamic_offset))
  9503          ctx->dynamic_offset -= cell_num_to_pop;
  9504
  9505      emit_operand(ctx, *(ctx->frame_offset));
  9506
  9507      (void)error_buf;
  9508      (void)error_buf_size;
  9509      return true;
  9510  }
